use super::*;
use semio_framework_value::{retirement::{RetireOwned,OwnedValueRetirementFactory},retained_clone::RetainedCloneSource};
use protocol::{PagedOneItemEdit,PagedOneItemEditStep};
fn issued_progress(step:&PagedOneItemEditStep<IdmlMutation>)->RetainedCloneProgress{match step{PagedOneItemEditStep::Progress(p)|PagedOneItemEditStep::Complete(p,_)|PagedOneItemEditStep::CompleteRows(p,_)|PagedOneItemEditStep::CompleteOutcome(p,..)|PagedOneItemEditStep::RefusedOutcome(p,_)=>*p}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{match RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096}){Ok((owner,_))=>owner,Err((error,_,_))=>panic!("{error}")}}
fn close_source<T:RetireOwned+Sync+'static>(owner:&mut RetainedCloneSource<T>){while !owner.terminal_is_empty(){let d=RetirementDemand{copy_bytes:owner.next_close_copy_byte_demand().unwrap(),capacity_bytes:owner.next_close_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_close_release_byte_demand().unwrap(),depth:owner.next_close_depth_demand().unwrap()};owner.close_step(grant(d)).unwrap();}}
fn close_messages(rows:Vec<MutationMessage>){let mut ledger=MutationMessageLedgerRetirement::new(String::new(),rows);while !ledger.terminal_is_empty(){let d=semio_framework_value::ErasedSnapshotRetirement::next_demand(&ledger,4096).unwrap();ledger.close_step(grant(d)).unwrap();}}
fn close_inverse(rows:Vec<IdmlMutation>,factory:&OwnedValueRetirementFactory<IdmlMutation>){let d=semio_framework_value_factory::vector::FactoryVectorRetirement::<IdmlMutation>::constructor_demand();let(mut owner,_)=semio_framework_value_factory::vector::FactoryVectorRetirement::admit(rows,grant(d)).unwrap_or_else(|(error,_)|panic!("{error}"));while !owner.terminal_is_empty(){let d=owner.demands(factory,4096).unwrap();owner.close_step(factory,grant(d)).unwrap();}}
fn close(owner:&mut protocol::MutationApplyEdit<IdmlSnapshot,IdmlMutation>,factory:&OwnedValueRetirementFactory<IdmlMutation>){owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){return;}let d=owner.close_demands(factory,4096).unwrap();assert_eq!(owner.close_step(factory,RetainedCloneGrant::default()).unwrap().progress(),Default::default());owner.close_step(factory,grant(d)).unwrap();}panic!("IDML genuine issuer close stalled");}
fn inputs(corpus:&serde_json::Value,row:&serde_json::Value)->(IdmlSnapshot,IdmlMutation){let base=IdmlSnapshot{dom_version:corpus["base"]["domVersion"].as_str().unwrap().into(),parts:corpus["base"]["parts"].as_array().unwrap().iter().map(|part|crate::schema::IdmlPart{path:part["path"].as_str().unwrap().into(),bytes:part["text"].as_str().unwrap().as_bytes().to_vec()}).collect()};let mutation=if row["kind"]=="replacePart"{IdmlMutation::ReplacePart{path:row["path"].as_str().unwrap().into(),bytes:row["text"].as_str().unwrap().as_bytes().to_vec()}}else{let mut document=base.clone();if row["append"].is_object(){document.parts.push(crate::schema::IdmlPart{path:row["append"]["path"].as_str().unwrap().into(),bytes:row["append"]["bytes"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect()});}if let Some(path)=row["removePath"].as_str(){document.parts.retain(|part|part.path!=path);}if let Some(order)=row["order"].as_array(){let before=document.parts;document.parts=order.iter().map(|index|before[index.as_u64().unwrap()as usize].clone()).collect();}IdmlMutation::ReplacePackage{document}};(base,mutation)}
#[test]
fn genuine_generic_issuer_decides_preflights_inverts_and_commits_idml(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){for body in [1024,4096,65536]{let(base,mutation)=inputs(&corpus,row);let original=base.clone();let event=mutation.clone();let expected=protocol::ColdMutation::diff(&mutation,&base);let mut post=base.clone();let mut base=source(base);let mut mutation=source(mutation);let factory=OwnedValueRetirementFactory::<IdmlMutation>::default();let mut owner=protocol::MutationApplyEdit::<IdmlSnapshot,IdmlMutation>::default();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);let mut turns=0;let(mut inverse,rows,admitted)=loop{turns+=1;assert!(turns<1000000);let d=owner.advance_demands(base.borrow(),mutation.borrow(),&post,body).unwrap();let under=owner.advance(base.borrow(),mutation.borrow(),&mut post,body,RetainedCloneGrant::default(),&mut receiving).unwrap();assert_eq!(issued_progress(&under),Default::default());let step=owner.advance(base.borrow(),mutation.borrow(),&mut post,body,grant(d),&mut receiving).unwrap();assert!(issued_progress(&step).fits(grant(d)));match step{PagedOneItemEditStep::Progress(_)=>{},PagedOneItemEditStep::CompleteOutcome(_,inverse,rows)=>break(inverse,rows,true),PagedOneItemEditStep::RefusedOutcome(_,rows)=>break(Vec::new(),rows,false),_=>panic!("unexpected issuer result")}};assert_eq!(admitted,row["admitted"].as_bool().unwrap());if admitted{let target=protocol::apply_diff_cold(expected.diff(),&original).unwrap();assert_eq!(post,target);assert_eq!(inverse.is_empty(),!row["changed"].as_bool().unwrap());let mut restored=post.clone();for mutation in &inverse{let decision=protocol::ColdMutation::diff(mutation,&restored);restored=protocol::apply_diff_cold(decision.diff(),&restored).unwrap();}assert_eq!(restored,original);}else{assert_eq!(post,original);}if let Some(code)=row["diagnostic"].as_str(){assert!(rows.iter().any(|message|message.code.0==code));}close_messages(rows);close_inverse(std::mem::take(&mut inverse),&factory);assert_eq!(base.borrow().get(),&original);assert_eq!(mutation.borrow().get(),&event);close(&mut owner,&factory);close_source(&mut mutation);close_source(&mut base);let mut post=source(post);close_source(&mut post);}}}
#[test]
fn cancellation_closes_real_semantic_and_central_issuer_frontiers(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for cut in [0,1,5,50,100,250]{let(base,mutation)=inputs(&corpus,&corpus["cases"][0]);let original=base.clone();let event=mutation.clone();let mut post=base.clone();let mut base=source(base);let mut mutation=source(mutation);let factory=OwnedValueRetirementFactory::<IdmlMutation>::default();let mut owner=protocol::MutationApplyEdit::<IdmlSnapshot,IdmlMutation>::default();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);for _ in 0..cut{let d=owner.advance_demands(base.borrow(),mutation.borrow(),&post,1024).unwrap();match owner.advance(base.borrow(),mutation.borrow(),&mut post,1024,grant(d),&mut receiving).unwrap(){PagedOneItemEditStep::Progress(_)=>{},PagedOneItemEditStep::CompleteOutcome(_,inverse,rows)=>{close_messages(rows);close_inverse(inverse,&factory);break;},PagedOneItemEditStep::RefusedOutcome(_,rows)=>{close_messages(rows);break;},_=>panic!("unexpected issuer frontier")}}assert_eq!(base.borrow().get(),&original);assert_eq!(mutation.borrow().get(),&event);close(&mut owner,&factory);close_source(&mut mutation);close_source(&mut base);let mut post=source(post);close_source(&mut post);}}
